mapper.sql:
teacher.user_type = 'ORGANIZATION' AND EXISTS ( SELECT 1 FROM sys_user_role teacher_role_assignment JOIN sys_role teacher_role ON teacher_role.id = teacher_role_assignment.role_id WHERE teacher_role_assignment.user_id = teacher.id AND teacher_role.role_code = 'TEACHER' AND teacher_role.status = 'ENABLED' ) AND school.organization_type = 'SCHOOL'
AND (
school.organization_path LIKE CONCAT(#{rootPath}, '%')
)
AND (teacher.username LIKE CONCAT('%', #{criteria.keyword}, '%') OR teacher.display_name LIKE CONCAT('%', #{criteria.keyword}, '%'))
AND school.id = #{criteria.schoolId}
AND teacher.status = #{criteria.status}
AND EXISTS ( SELECT 1 FROM edu_teacher_class class_filter WHERE class_filter.teacher_user_id = teacher.id AND class_filter.class_organization_id = #{criteria.classOrganizationId} AND class_filter.status = 'ACTIVE' )

mapper.select:
SELECT EXISTS(
    SELECT 1 FROM sys_user
    WHERE mobile = #{mobile} AND id <> #{teacherUserId}
)

SELECT EXISTS(
    SELECT 1
    FROM learn_task_assignment
    WHERE current_reviewer_id = #{teacherUserId}
      AND current_status = 'PENDING_REVIEW'
)
